{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']

    # Validate required fields per segment
    for i, seg in enumerate(segments):
        if 'name' not in seg or 'importance' not in seg or 'minimum' not in seg or 'capacity' not in seg:
            raise ValueError(f"Segment {i} missing required fields")
        if seg['minimum'] < 0 or seg['capacity'] < seg['minimum']:
            raise ValueError(f"Segment {i}: invalid min/capacity")

    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)

    if budget < total_min or budget > total_cap:
        raise ValueError(f"Budget {budget} not in [{total_min}, {total_cap}]")

    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    remaining = budget - total_min

    # Greedy allocation
    while remaining > 0:
        best_idx = None
        best_score = None
        for i, seg in enumerate(segments):
            if alloc[i] >= seg['capacity']:
                continue
            # Score = importance / (next position = current_alloc + 1)
            score = seg['importance'] / (alloc[i] + 1)
            if best_idx is None or score > best_score:
                best_score = score
                best_idx = i
        if best_idx is None:
            # Should not happen because budget <= total_cap
            break
        alloc[best_idx] += 1
        remaining -= 1

    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    total = sum(alloc)
    return {
        'allocations': alloc,
        'by_name': by_name,
        'total': total
    }"}
